use mathlab_engine::rust_program::{scientific_v2::*,ProgramStatusV1,ProgramCheckpointV1,ProgramCancelReasonV1,ProgramCancelResultV1};
use mathlab_language::program::*;
use std::{sync::Arc,future::Future};
fn module(s:&str)->Arc<ProgramModuleV1>{Arc::new(parse_program_v1(2101,Arc::from(s)).unwrap())}
fn run(s:&mut ScientificProgramSessionV2,src:&str)->ScientificProgramOutcomeV2{s.prepare(module(src),Default::default()).unwrap().execute()}
fn assert_real(s:&ScientificProgramSessionV2,name:&str,words:&[f64]){let v=s.binding(name).unwrap();assert!(!v.is_sparse());assert_eq!(v.stored_len(),words.len());for (i,x)in words.iter().enumerate(){assert_eq!(v.dense_component(i).unwrap().re,*x)}}
#[test]fn csc_user_functions_dispatch_copy_isolation_and_explicit_refusals(){
 let mut s=ScientificProgramSessionV2::new().unwrap();let o=run(&mut s,"A=sparse([2;1;2],[2;1;2],[3;4;5],2,2);saved=A;[Y,kind,count,capacity,axes,total]=f(A);after=9;\nfunction [y,k,c,z,s,n]=f(a)\na=sparse(1,1,7,2,2);y=a*[1;2];k=issparse(a);c=nnz(a);z=nzmax(a);s=size(a);n=numel(a);end");assert_eq!(o.status,ProgramStatusV1::Success,"{:?}",o.error);assert!(!o.stats.ledger_poisoned);let a=s.binding("A").unwrap().csc_view().unwrap();assert_eq!(a.column_pointers(),[0,1,2]);assert_eq!(a.row_indices(),[0,1]);match a.values(){ScientificCscValuesV1::Real(x)=>assert_eq!(x,[4.,8.]),_=>panic!()};assert_real(&s,"Y",&[7.,0.]);assert_eq!(s.binding("kind").unwrap().scalar().unwrap(),1.);assert_real(&s,"axes",&[2.,2.]);assert_eq!(s.binding("total").unwrap().scalar().unwrap(),4.);assert!(s.binding("a").is_none());
 for bad in ["bad=A+1;","bad=A(1);","A(1)=8;","for k=A;bad=1;end"]{let before=s.context();let o=run(&mut s,bad);assert_eq!(o.status,ProgramStatusV1::Error);assert_eq!(o.error.unwrap().code,ScientificProgramErrorCodeV2::UnsupportedFeature);assert_eq!(s.context().revision,before.revision);assert!(s.binding("bad").is_none());assert_eq!(run(&mut s,"recovered=1;").status,ProgramStatusV1::Success)}
}
#[test]fn native_empty_scalar_nan_and_ieee_matrix_cases(){
 let mut s=ScientificProgramSessionV2::new().unwrap();let o=run(&mut s,"A=sparse([],1,complex(nan(),2),2,2);k=issparse(A);c=nnz(A);z=nzmax(A);Y=A*[inf();1];B=sparse(1,1,complex(inf(),1),2,2);Z=B*[0;1];C=sparse(1,1,complex(2,3),2,2);W=C*[inf();1];");assert_eq!(o.status,ProgramStatusV1::Success,"{:?}",o.error);assert_eq!(s.binding("A").unwrap().csc_view().unwrap().nzmax(),1);assert!(!s.binding("A").unwrap().is_complex());assert_real(&s,"Y",&[0.,0.]);assert!(!s.binding("Z").unwrap().is_complex());assert!(s.binding("Z").unwrap().dense_component(0).unwrap().re.is_nan());let w=s.binding("W").unwrap().dense_component(0).unwrap();assert_eq!(w,Complex64V1{re:f64::INFINITY,im:f64::INFINITY});
 let o=run(&mut s,"prefix=11;N=sparse(1,1,nan(),2,2);if N;unreached=1;end");assert_eq!(o.status,ProgramStatusV1::Error);assert_eq!(o.error.unwrap().code,ScientificProgramErrorCodeV2::Type);assert!(s.binding("unreached").is_none());assert_eq!(s.binding("prefix").unwrap().scalar().unwrap(),11.);
}
#[test]fn generic_poisson_pcg_tiny_complete_values_and_quota_instrumentation(){
 let src=include_str!("../../../examples/scientific/poisson_pcg.m").replacen("n=32;","n=4;",1);let mut s=ScientificProgramSessionV2::new().unwrap();let o=run(&mut s,&src);assert_eq!(o.status,ProgramStatusV1::Success,"{:?}",o.error);assert_eq!(s.binding("flag").unwrap().scalar().unwrap(),0.);let iterations=s.binding("iterations").unwrap().scalar().unwrap();assert!(iterations>0.&&iterations<=512.);let x=s.binding("solution").unwrap();assert_eq!(&*x.axes(),[64,1]);for z in 0..4{for y in 0..4{for r in 0..4{let q=|i:usize|((i+1)*(4-i))as f64;let expected=q(r)*q(y)*q(z);assert!((x.dense_component(r+4*y+16*z).unwrap().re-expected).abs()<2f64.powi(-28)*expected)}}}assert_eq!(s.binding("A").unwrap().stored_len(),352);assert!(o.stats.sparse_constructors>=1);assert!(o.stats.sparse_products>=iterations as u64);assert!(o.stats.primitive_steps<1_000_000_000);assert!(o.stats.transitions<5_000_000);assert!(o.stats.peak_live_payload_bytes<=64<<20);assert!(!o.stats.ledger_poisoned);
}
#[test]fn repeated_replacement_releases_scratch_and_operation_ownership(){
 let mut s=ScientificProgramSessionV2::new().unwrap();let one=run(&mut s,"A=sparse([2;1;2],[2;1;2],[3;4;5],2,2);Y=A*[1;2];");assert_eq!(one.status,ProgramStatusV1::Success);let many=run(&mut s,"for iteration=1:200;A=sparse([2;1;2],[2;1;2],[3;4;5],2,2);Y=A*[1;2];end");assert_eq!(many.status,ProgramStatusV1::Success,"{:?}",many.error);assert_eq!(many.stats.sparse_constructors,200);assert_eq!(many.stats.sparse_products,200);assert!(!many.stats.ledger_poisoned);assert!(many.stats.peak_live_payload_bytes<4096);assert_real(&s,"Y",&[4.,16.]);
}
const PHASES:&str="before=7;i=[2;1;2];j=[2;1;2];v=[3;4;5];A=sparse(i,j,v,2,2);saved=A;Y=A*[1;2];A=sparse(1,1,9,2,2);last=1;";
fn prefix(s:&ScientificProgramSessionV2){assert_eq!(s.binding("seed").unwrap().scalar().unwrap(),17.);if let Some(y)=s.binding("Y"){assert_eq!(y.dense_component(0).unwrap().re,4.);assert_eq!(y.dense_component(1).unwrap().re,16.)}if let Some(a)=s.binding("A"){let a=a.csc_view().unwrap();assert!(a.nnz()==1||a.nnz()==2)}if let Some(saved)=s.binding("saved"){assert_eq!(saved.csc_view().unwrap().nnz(),2)}}
#[test]fn every_sparse_continuation_stop_drop_prefix_and_fresh_recovery(){
 let mut baseline=ScientificProgramSessionV2::new().unwrap();run(&mut baseline,"seed=17;");let mut polls=0;{let request=baseline.prepare(module(PHASES),Default::default()).unwrap();let future=request.execute_cooperatively(|_,_|{});assert!(std::mem::size_of_val(&future)<=1<<20);let mut f=std::pin::pin!(future);let mut cx=std::task::Context::from_waker(std::task::Waker::noop());loop{polls+=1;if let std::task::Poll::Ready(o)=f.as_mut().poll(&mut cx){assert_eq!(o.status,ProgramStatusV1::Success);break}}}assert!(polls>20);
 for at in 0..polls-1{for stop in [false,true]{let mut s=ScientificProgramSessionV2::new().unwrap();run(&mut s,"seed=17;");let handle;{let request=s.prepare(module(PHASES),Default::default()).unwrap();handle=request.cancel_handle();let f=request.execute_cooperatively(|_,_|{});let mut f=std::pin::pin!(f);let mut cx=std::task::Context::from_waker(std::task::Waker::noop());for _ in 0..at{assert!(f.as_mut().poll(&mut cx).is_pending())}if stop{assert!(matches!(handle.request_stop(),ProgramCancelResultV1::Accepted(_)));loop{if let std::task::Poll::Ready(o)=f.as_mut().poll(&mut cx){assert_eq!(o.status,ProgramStatusV1::Cancelled(ProgramCancelReasonV1::UserStop));assert!(!o.stats.ledger_poisoned);break}}}}if stop{assert_eq!(handle.request_stop(),ProgramCancelResultV1::AlreadyAccepted(ProgramCancelReasonV1::UserStop));}else{assert_eq!(handle.request_stop(),ProgramCancelResultV1::TooLate);}prefix(&s);let live=s.bindings().map(|b|b.value.payload_bytes()).sum::<usize>();let o=run(&mut s,"recovered=1;");assert_eq!(o.status,ProgramStatusV1::Success);assert_eq!(o.stats.peak_live_payload_bytes,live+8);assert!(!o.stats.ledger_poisoned)}}
}
#[test]fn sparse_publication_stop_barrier_and_fuel_keep_prior_binding(){
 for (point,changed)in [(ProgramCheckpointV1::BeforePublish,false),(ProgramCheckpointV1::AfterBarrier,true),(ProgramCheckpointV1::AfterPublish,true)]{let mut s=ScientificProgramSessionV2::new().unwrap();run(&mut s,"A=sparse(1,1,3,2,2);");let mut fired=false;let o=s.prepare(module("A=sparse(2,2,9,2,2);after=1;"),Default::default()).unwrap().execute_controlled(|at,h|{if at==point&&!fired{fired=true;h.request_stop();}});assert_eq!(o.status,ProgramStatusV1::Cancelled(ProgramCancelReasonV1::UserStop));assert_eq!(s.binding("A").unwrap().csc_view().unwrap().row_indices(),if changed{&[1][..]}else{&[0][..]});assert!(s.binding("after").is_none());}
 let mut s=ScientificProgramSessionV2::new().unwrap();run(&mut s,"seed=17;");for options in [ScientificProgramOptionsV2{primitive_fuel:1,..Default::default()},ScientificProgramOptionsV2{transition_fuel:1,..Default::default()}]{let o=s.prepare(module(PHASES),options).unwrap().execute();assert_eq!(o.status,ProgramStatusV1::Resource);assert!(s.binding("last").is_none());assert_eq!(run(&mut s,"recovered=1;").status,ProgramStatusV1::Success)}
}
#[test]fn zero_height_dense_literal_and_zero_column_sparse_product_preserve_shapes(){let mut s=ScientificProgramSessionV2::new().unwrap();let o=run(&mut s,"R=[zeros(0,257);zeros(0,257)];A=sparse([],[],[],0,0);Y=A*zeros(0,257);after=1;");assert_eq!(o.status,ProgramStatusV1::Success,"{:?}",o.error);assert_eq!(&*s.binding("R").unwrap().axes(),[0,257]);assert_eq!(&*s.binding("Y").unwrap().axes(),[0,257]);assert!(o.stats.primitive_steps>=257);assert!(!o.stats.ledger_poisoned)}
